"""Bloat donor images catalog — reads data/bloat.json (generated by tools/gen_bloat_json.py).

Catalog layout (matches ./bloat storage): model -> region -> filename.
"""

from __future__ import annotations

import gzip
import hashlib
import json
from dataclasses import dataclass
from pathlib import Path

CATALOG_PATH = Path(__file__).resolve().parent.parent / "data" / "bloat.json"


@dataclass
class BloatEntry:
    model: str  # directory name under bloat/
    region: str
    filename: str
    url: str
    bytes: int
    sha256: str  # of the downloaded asset (gzip included)
    raw_bytes: int
    raw_sha256: str  # of the final .img
    gzipped: bool


def load_catalog(path: Path = CATALOG_PATH) -> list[BloatEntry]:
    data = json.loads(Path(path).read_text())
    entries = []
    for model, regions in data.items():
        for region, files in regions.items():
            for filename, e in files.items():
                entries.append(
                    BloatEntry(
                        model=model,
                        region=region,
                        filename=filename,
                        url=e["url"],
                        bytes=e["bytes"],
                        sha256=e["sha256"],
                        raw_bytes=e["raw_bytes"],
                        raw_sha256=e["raw_sha256"],
                        gzipped=e["encoding"] == "gzip",
                    )
                )
    return entries


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(4 * 1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def gunzip_to(tmp: Path, dest: Path) -> None:
    """Decompress tmp (gzip) into dest."""
    with gzip.open(tmp, "rb") as src, open(dest, "wb") as out:
        for chunk in iter(lambda: src.read(4 * 1024 * 1024), b""):
            out.write(chunk)
